import{_ as e,o as t,c as s,aw as n}from"./chunks/framework.DLufY-ao.js";const h=JSON.parse('{"title":"Модель распространения событий","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/js-web-api/dom-events/propagation-model.md","filePath":"wiki/dev-commit/js/js-web-api/dom-events/propagation-model.md"}'),l={name:"wiki/dev-commit/js/js-web-api/dom-events/propagation-model.md"};function p(o,a,i,r,d,c){return t(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="модель-распространения-событии" tabindex="-1">Модель распространения событий <a class="header-anchor" href="#модель-распространения-событии" aria-label="Permalink to &quot;Модель распространения событий&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p><a href="https://www.w3.org/TR/DOM-Level-3-Events/" target="_blank" rel="noreferrer">https://www.w3.org/TR/DOM-Level-3-Events/</a></p></div><h2 id="dom-events-модель-распространения-событии" tabindex="-1">DOM Events - модель распространения событий <a class="header-anchor" href="#dom-events-модель-распространения-событии" aria-label="Permalink to &quot;DOM Events - модель распространения событий&quot;">​</a></h2><table tabindex="0"><thead><tr><th>1</th><th>Фаза погружения/перехвата (Capturing phase)</th><th>Event.CAPTURING_PHASE=1</th><th>Идет от родительского элемента (document или window в зависимости от события) до целевого</th></tr></thead><tbody><tr><td>2</td><td>Фаза цели (Target phase)</td><td>Event.AT_TARGET=2</td><td>Событие достигло целевого (исходного) элемента</td></tr><tr><td>3</td><td>Фаза всплытия (Bubbling stage)</td><td>Event.BUBBLING_PAGE=3</td><td>Идёт от целевого элемента до родительского (document или window</td></tr></tbody></table><h2 id="необходимость-всплытия-и-погружения" tabindex="-1">Необходимость всплытия и погружения <a class="header-anchor" href="#необходимость-всплытия-и-погружения" aria-label="Permalink to &quot;Необходимость всплытия и погружения&quot;">​</a></h2><ul><li>Реализация делегирования</li><li>Настройка дефолтных обработчиков</li></ul><h2 id="алгоритм-работы" tabindex="-1">Алгоритм работы <a class="header-anchor" href="#алгоритм-работы" aria-label="Permalink to &quot;Алгоритм работы&quot;">​</a></h2><ul><li>При наступлении события – самый глубоко вложенный элемент, на котором оно произошло, помечается как «целевой» event.target</li><li>Затем событие сначала двигается вниз от корня документа к event.target, по пути вызывая обработчики, поставленные через addEventListener(...., {capture: true})</li><li>Далее обработчики вызываются на целевом элементе</li><li>Далее событие двигается от event.target вверх к корню документа, по пути вызывая обработчики, поставленные через <code>on&lt;event&gt;</code> и addEventListener без третьего аргумента или с третьим аргументом равным false</li></ul><h2 id="схема-работы" tabindex="-1">Схема работы <a class="header-anchor" href="#схема-работы" aria-label="Permalink to &quot;Схема работы&quot;">​</a></h2><ul><li>На картинке клик по ячейке td, расположенной внутри таблицы</li><li>При клике на td событие перемещается по цепочке родителей сначала вниз к элементу (погружается), затем оно достигает целевой элемент (фаза цели), а потом идёт наверх (всплытие), вызывая по пути обработчики</li></ul><hr><h2 id="пример" tabindex="-1">Пример <a class="header-anchor" href="#пример" aria-label="Permalink to &quot;Пример&quot;">​</a></h2><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span>&amp;lt;form&amp;gt;FORM</span></span>
<span class="line"><span>  &amp;lt;div&amp;gt;DIV</span></span>
<span class="line"><span>    &amp;lt;p&amp;gt;P&amp;lt;/p&amp;gt;</span></span>
<span class="line"><span>  &amp;lt;/div&amp;gt;</span></span>
<span class="line"><span>&amp;lt;/form&amp;gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&amp;lt;script&amp;gt;</span></span>
<span class="line"><span>  for (let elem of document.querySelectorAll(&#39;*&#39;)) {</span></span>
<span class="line"><span>    elem.addEventListener(&quot;click&quot;, (e) =&amp;gt; alert(\`Погружение: \${elem.tagName}\`), true);</span></span>
<span class="line"><span>    elem.addEventListener(&quot;click&quot;, (e) =&amp;gt; alert(\`Всплытие: \${elem.tagName}\`));</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>&amp;lt;/script&amp;gt;</span></span></code></pre></div><ol><li>HTML → BODY → FORM → DIV (фаза погружения, первый обработчик)</li><li>P (фаза цели, срабатывают обработчики, установленные и на погружение и на всплытие, так что выведется два раза)</li><li>DIV → FORM → BODY → HTML (фаза всплытия, второй обработчик)</li></ol><h2 id="прочее" tabindex="-1">Прочее <a class="header-anchor" href="#прочее" aria-label="Permalink to &quot;Прочее&quot;">​</a></h2><ul><li>На каждой фазе разные обработчики на одном элементе срабатывают в порядке назначения</li><li>Если несколько обработчиков одного события, назначенных addEventListener на один элемент, в рамках одной фазы, то их порядок срабатывания – тот же, в котором они установлены</li></ul><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">element.</span><span style="color:#4078F2;">addEventListener</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;click&quot;</span><span style="color:#383A42;">, e </span><span style="color:#A626A4;">=&gt;</span><span style="color:#4078F2;"> alert</span><span style="color:#383A42;">(</span><span style="color:#986801;">1</span><span style="color:#383A42;">)); </span><span style="color:#A0A1A7;font-style:italic;">// всегда сработает перед следующим</span></span>
<span class="line"><span style="color:#383A42;">element.</span><span style="color:#4078F2;">addEventListener</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;click&quot;</span><span style="color:#383A42;">, e </span><span style="color:#A626A4;">=&gt;</span><span style="color:#4078F2;"> alert</span><span style="color:#383A42;">(</span><span style="color:#986801;">2</span><span style="color:#383A42;">));</span></span></code></pre></div>`,17)])])}const u=e(l,[["render",p]]);export{h as __pageData,u as default};
